typedef int l_int32;

l_int32 generateImageViewer(const char* dirin, const char* dirout, const char* rootname, l_int32 thumbwidth, l_int32 viewwidth) {
    if (!dirin || !dirout || !rootname) {
        fprintf(stderr, "Invalid input parameters.\n");
        return -1;
    }

    // Create output directory if it doesn't exist
    struct stat st;
    if (stat(dirout, &st) == -1) {
        if (mkdir(dirout, 0777) == -1) {
            perror("Failed to create output directory");
            return -1;
        }
    }

    // Open input directory
    DIR* dp = opendir(dirin);
    if (!dp) {
        perror("Failed to open input directory");
        return -1;
    }

    // Retrieve image filenames
    char** imageFiles = NULL;
    int count = 0;
    struct dirent* entry;
    while ((entry = readdir(dp)) != NULL) {
        if (entry->d_type == DT_REG) {
            // Simple check for image extensions (could be extended)
            const char* ext = strrchr(entry->d_name, '.');
            if (ext && (!strcmp(ext, ".jpg") || !strcmp(ext, ".jpeg") || !strcmp(ext, ".png"))) {
                imageFiles = realloc(imageFiles, (count + 1) * sizeof(char*));
                imageFiles[count] = strdup(entry->d_name);
                count++;
            }
        }
    }
    closedir(dp);

    if (count == 0) {
        fprintf(stderr, "No image files found in input directory.\n");
        return -1;
    }

    // Construct paths for HTML files
    char mainHtmlPath[1024];
    char linksHtmlPath[1024];
    snprintf(mainHtmlPath, sizeof(mainHtmlPath), "%s/%s.html", dirout, rootname);
    snprintf(linksHtmlPath, sizeof(linksHtmlPath), "%s/%s_links.html", dirout, rootname);

    // Generate main HTML viewer file
    FILE* mainHtml = fopen(mainHtmlPath, "w");
    if (!mainHtml) {
        perror("Failed to create main HTML file");
        return -1;
    }

    fprintf(mainHtml, "<!DOCTYPE html>\n<html>\n<head>\n");
    fprintf(mainHtml, "<title>%s</title>\n", rootname);
    fprintf(mainHtml, "</head>\n<body>\n");
    fprintf(mainHtml, "<h1>%s</h1>\n", rootname);
    fprintf(mainHtml, "<div id=\"gallery\">\n");

    for (int i = 0; i < count; i++) {
        char thumbPath[1024];
        char viewPath[1024];
        char thumbName[1024];
        char viewName[1024];

        // Construct image paths and names
        snprintf(thumbName, sizeof(thumbName), "%s_thumb_%s", rootname, imageFiles[i]);
        snprintf(viewName, sizeof(viewName), "%s_view_%s", rootname, imageFiles[i]);

        // Simulate thumbnail and view image generation (this would be replaced by actual image processing)
        // For now, we just write the HTML placeholders
        fprintf(mainHtml, "<a href=\"#\" onclick=\"showImage('%s')\">\n", viewName);
        fprintf(mainHtml, "<img src=\"%s\" alt=\"%s\" width=\"%d\" />\n", thumbName, imageFiles[i], thumbwidth);
        fprintf(mainHtml, "</a>\n");
    }

    fprintf(mainHtml, "</div>\n");
    fprintf(mainHtml, "<div id=\"viewer\"></div>\n");
    fprintf(mainHtml, "<script>\n");
    fprintf(mainHtml, "function showImage(name) {\n");
    fprintf(mainHtml, "  document.getElementById('viewer').innerHTML = '<img src=\"' + name + '\" alt=\"Image\" width=\"%d\" />';", viewwidth);
    fprintf(mainHtml, "}\n");
    fprintf(mainHtml, "</script>\n");
    fprintf(mainHtml, "</body>\n</html>\n");

    fclose(mainHtml);

    // Generate HTML for image links
    FILE* linksHtml = fopen(linksHtmlPath, "w");
    if (!linksHtml) {
        perror("Failed to create links HTML file");
        return -1;
    }

    fprintf(linksHtml, "<!DOCTYPE html>\n<html>\n<head>\n");
    fprintf(linksHtml, "<title>%s - Links</title>\n", rootname);
    fprintf(linksHtml, "</head>\n<body>\n");
    fprintf(linksHtml, "<h1>%s - Image Links</h1>\n", rootname);
    fprintf(linksHtml, "<ul>\n");

    for (int i = 0; i < count; i++) {
        char viewName[1024];
        snprintf(viewName, sizeof(viewName), "%s_view_%s", rootname, imageFiles[i]);
        fprintf(linksHtml, "<li><a href=\"%s.html#%s\" target=\"_blank\">%s</a></li>\n", rootname, viewName, imageFiles[i]);
    }

    fprintf(linksHtml, "</ul>\n</body>\n</html>\n");

    fclose(linksHtml);

    // Free memory
    for (int i = 0; i < count; i++) {
        free(imageFiles[i]);
    }
    free(imageFiles);

    return 0;
}

