// Assuming l_int32 is defined in the project
typedef int l_int32;

l_int32 generate_html_image_viewer(const char* dirin, const char* dirout, const char* rootname, l_int32 thumbwidth, l_int32 viewwidth) {
    // Validate inputs
    if (!dirin || !dirout || !rootname) {
        return 1; // Invalid parameters
    }

    // Create output directory if it doesn't exist
    struct stat st = {0};
    if (stat(dirout, &st) == -1) {
        if (mkdir(dirout, 0777) != 0) {
            return 2; // Directory creation failed
        }
    }

    // Open input directory
    DIR *dp;
    struct dirent *ep;
    dp = opendir(dirin);
    if (!dp) {
        return 3; // Could not open input directory
    }

    // Prepare output file paths
    char main_html_path[1024];
    char links_html_path[1024];
    snprintf(main_html_path, sizeof(main_html_path), "%s/%s.html", dirout, rootname);
    snprintf(links_html_path, sizeof(links_html_path), "%s/%s_links.html", dirout, rootname);

    // Open main HTML file
    FILE *main_html = fopen(main_html_path, "w");
    if (!main_html) {
        closedir(dp);
        return 4; // Could not open main HTML file
    }

    // Open links HTML file
    FILE *links_html = fopen(links_html_path, "w");
    if (!links_html) {
        fclose(main_html);
        closedir(dp);
        return 5; // Could not open links HTML file
    }

    // Write HTML headers
    fprintf(main_html, "<!DOCTYPE html>\n<html>\n<head>\n<title>%s</title>\n</head>\n<body>\n", rootname);
    fprintf(links_html, "<!DOCTYPE html>\n<html>\n<head>\n<title>%s Links</title>\n</head>\n<body>\n", rootname);

    // Process each file in the input directory
    while ((ep = readdir(dp))) {
        // Skip . and ..
        if (strcmp(ep->d_name, ".") == 0 || strcmp(ep->d_name, "..") == 0) {
            continue;
        }

        // Assume all files in the directory are images (this should be enhanced with file type validation)
        char thumb_path[1024];
        char view_path[1024];
        char link_path[1024];

        // Generate paths for thumbnails and view images
        snprintf(thumb_path, sizeof(thumb_path), "%s/thumbs/%s", dirout, ep->d_name);
        snprintf(view_path, sizeof(view_path), "%s/views/%s", dirout, ep->d_name);
        snprintf(link_path, sizeof(link_path), "%s_views/%s", rootname, ep->d_name);

        // Write HTML entries for thumbnails and links
        fprintf(main_html, "<a href=\"%s\"><img src=\"%s\" width=\"%d\" alt=\"%s\"></a>\n",
                link_path, thumb_path, thumbwidth, ep->d_name);
        fprintf(links_html, "<p><a href=\"%s\">View %s</a></p>\n", link_path, ep->d_name);
    }

    // Write HTML footers
    fprintf(main_html, "</body>\n</html>\n");
    fprintf(links_html, "</body>\n</html>\n");

    // Close files and directory
    fclose(main_html);
    fclose(links_html);
    closedir(dp);

    return 0; // Success
}
